"""Draft a schematic sheet from a DesignPlan: place, route, check, repeat.

The draft is a template for the engine's sch_preview_template and
sch_draw_template, so the engine's own checker (shorts, netlist pin by pin,
crossings, wires through bodies, text on text) judges every candidate, and
what is drawn in Altium is exactly what was scored here.

The search is simulated annealing over the placement (``place.State``):
move a part, move a column, slide a shunt along its pin, flip a series
part, swap two parts. Each candidate is routed in full and scored:

    router cost (wire length, corners, crossings, symbols, labels)
  + the checker's findings
  + sheet area
  + drawing conventions (inputs on the left edge, outputs on the right)

It is deterministic for a given seed and time budget.
"""
from __future__ import annotations

import math
import random
import time
from dataclasses import dataclass
from typing import Any, Optional

from eda_agent.design import sch_template as st

from .circuit import GRID, Circuit, from_plan, split
from .place import Layout, Plan, State, initial_state, make_plan, realize
from .route import Costs, Routed, route

#: Altium sheet sizes in mils (width, height).
SHEETS = {"A4": (11500, 7600), "A3": (15500, 11100), "A2": (22000, 15500),
          "A1": (31500, 22300), "A0": (44600, 31500), "A": (9500, 7500),
          "B": (15000, 9500), "C": (20000, 15000), "D": (32000, 20000),
          "E": (42000, 32000)}
#: Kept clear: the border all round and the title block at the bottom.
_MARGIN = 600
_TITLE = 1400

#: What the checker's findings cost, per finding.
_WARNING_COST = {"crossing": 0.0, "through_body": 60.0, "text_overlap": 8.0,
                 "dangling": 30.0, "stacked": 20.0, "off_grid": 50.0}
_ERROR_COST = 500.0
_AREA_COST = 0.03          # per grid cell of the drawing's box
_CONVENTION_COST = 100.0   # an input connector off the left edge, an output off the right
_FLOW_COST = 15.0          # two connected parts out of signal order, left to right
_UPRIGHT_COST = 6.0        # a two-pin part in a path standing upright, not across
_TETHER_COST = 0.3         # per grid step a hung part strays from its pin
_OUTLINE_COST = 60.0       # two parts whose Altium outlines meet (the audit's overlap)


@dataclass
class Candidate:
    score: float
    state: State
    layout: Optional[Layout] = None
    routed: Optional[Routed] = None
    template: Optional[dict] = None
    drawing: Any = None


def _template(c: Circuit, lay: Layout, routed: Routed) -> dict:
    parts = []
    for ref in sorted(lay.parts):
        p, part = lay.parts[ref], c.parts[ref]
        rotation, mirrored = split(p.rotation)
        entry = {"designator": ref, "lib_reference": part.lib_ref,
                 "x": p.x, "y": p.y, "rotation": rotation}
        if mirrored:
            entry["mirrored"] = True
        if part.lib_path:
            entry["library_path"] = part.lib_path
        if part.value:
            entry["value"] = part.value
        parts.append(entry)
    nets = {n.name: [f"{r}.{num}" for r, num in n.pins] for n in c.nets.values()}
    return {"parts": parts, "wires": routed.wires, "ports": routed.ports,
            "labels": routed.labels, "nets": nets}


def _conventions(plan: Plan, lay: Layout) -> int:
    """Input connectors left of everything else, outputs right of it."""
    c = plan.circuit
    bad = 0
    xs = {ref: (min(q[0] for q in p.body | p.lines | set(p.ends)),
                max(q[0] for q in p.body | p.lines | set(p.ends)))
          for ref, p in lay.parts.items()}
    inner = [ref for ref in lay.parts if c.parts[ref].kind != "connector"]
    if not inner:
        return 0
    left_edge = min(xs[r][0] for r in inner)
    right_edge = max(xs[r][1] for r in inner)
    for ref, part in c.parts.items():
        if part.kind != "connector" or ref not in xs:
            continue
        if part.side == "left" and xs[ref][1] > left_edge:
            bad += 1
        if part.side == "right" and xs[ref][0] < right_edge:
            bad += 1
    return bad


def _flow(plan: Plan, lay: Layout) -> int:
    """Pairs of connected parts whose left-to-right order is not their
    signal order (the columns): what keeps a drawing reading as it flows
    when net labels would let any part go anywhere."""
    c = plan.circuit
    col = plan.columns
    mid = {ref: sum(q[0] for q in p.body) / max(1, len(p.body))
           for ref, p in lay.parts.items() if ref in col}
    bad = 0
    for net in c.nets.values():
        if net.kind == "ground":
            continue
        refs = sorted({r for r, _ in net.pins if r in mid})
        for i, a in enumerate(refs):
            for b in refs[i + 1:]:
                if col[a] != col[b] and (col[a] < col[b]) != (mid[a] < mid[b]):
                    bad += 1
    return bad


def _upright(plan: Plan, lay: Layout) -> int:
    """Two-pin parts in a path drawn upright: a series resistor lies across
    the line it is in."""
    c = plan.circuit
    n = 0
    for ref in plan.skeleton:
        if c.parts[ref].kind == "two" and ref in lay.parts:
            if lay.parts[ref].pins and lay.parts[ref].pins[0].orientation in (1, 3):
                n += 1
    return n


def outline_overlaps(lay: Layout) -> list[tuple[str, str]]:
    """Pairs of parts whose outlines meet, as design_audit_schematic finds
    them on the drawn sheet: Altium's bounding rectangles (graphics and
    pins), touching included. A live draft passed every template check and
    the audit still reported a diode's pin running into a connector's box."""
    items = sorted(lay.parts.values(), key=lambda p: p.ref)
    out = []
    for i, a in enumerate(items):
        for b in items[i + 1:]:
            if (min(a.outline[2], b.outline[2]) >= max(a.outline[0], b.outline[0])
                    and min(a.outline[3], b.outline[3]) >= max(a.outline[1], b.outline[1])):
                out.append((a.ref, b.ref))
    return out


def evaluate(plan: Plan, state: State, attached: set[str],
             costs: Optional[Costs] = None) -> Candidate:
    lay = realize(plan, state)
    if lay.violations:
        return Candidate(1e5 + 1e3 * lay.violations, state, lay)
    routed = route(plan.circuit, lay, attached, costs)
    template = _template(plan.circuit, lay, routed)
    try:
        d = st.build(template, lay.pins())
    except st.TemplateError:
        return Candidate(1e6, state, lay, routed, template)
    score = routed.cost + _ERROR_COST * len(d.errors)
    for w in d.warnings:
        score += _WARNING_COST.get(w.get("check"), 10.0)
    x0, y0, x1, y1 = lay.bounds
    score += _AREA_COST * (x1 - x0 + 1) * (y1 - y0 + 1)
    score += _CONVENTION_COST * _conventions(plan, lay)
    score += _FLOW_COST * _flow(plan, lay)
    score += _UPRIGHT_COST * _upright(plan, lay)
    score += _TETHER_COST * sum(abs(dx) + abs(dy) for _, dx, dy in state.attached.values())
    score += _OUTLINE_COST * len(outline_overlaps(lay))
    return Candidate(score, state, lay, routed, template, d)


def _pull(plan: Plan, t: State, ref: str, rng: random.Random) -> None:
    """Move a part part-way toward the parts it is wired to (force-directed)."""
    c = plan.circuit
    xs, ys = [], []
    for net in set(c.nets_of(ref).values()):
        if c.nets[net].kind == "ground":
            continue
        for other, _ in c.nets[net].pins:
            if other != ref and other in t.skeleton:
                xs.append(t.skeleton[other][0])
                ys.append(t.skeleton[other][1])
    if not xs:
        return
    x, y, rot = t.skeleton[ref]
    f = rng.choice((0.3, 0.5, 0.8))
    nx = x + int((sum(xs) / len(xs) - x) * f) // GRID * GRID
    ny = y + int((sum(ys) / len(ys) - y) * f) // GRID * GRID
    t.skeleton[ref] = (nx, ny, rot)


def _neighbour(plan: Plan, s: State, rng: random.Random) -> State:
    t = s.copy()
    sk = list(t.skeleton)
    r = rng.random()
    if r < 0.28 or not t.attached and r < 0.50:
        ref = rng.choice(sk)
        x, y, rot = t.skeleton[ref]
        d = rng.choice((-3, -2, -1, 1, 2, 3)) * GRID
        t.skeleton[ref] = (x + d, y, rot) if rng.random() < 0.5 else (x, y + d, rot)
    elif r < 0.50:
        ref = rng.choice(sorted(t.attached))
        ai, ox, oy = t.attached[ref]
        what = rng.random()
        step = rng.choice((-3, -2, -1, 1, 2, 3))
        if what < 0.45:
            ox += step
        elif what < 0.9:
            oy += step
        else:
            ai += 1
        t.attached[ref] = (ai % len(plan.anchors[ref]), ox, oy)
    elif r < 0.62:
        # Open or close the gap at one x: everything right of it moves.
        cut = rng.choice([t.skeleton[q][0] for q in sk])
        d = rng.choice((-2, -1, 1, 2)) * GRID
        for q in sk:
            x, y, rot = t.skeleton[q]
            if x >= cut:
                t.skeleton[q] = (x + d, y, rot)
    elif r < 0.70:
        flips = [q for q in sk if len(plan.rotations.get(q, ())) > 1]
        if flips:
            q = rng.choice(flips)
            x, y, rot = t.skeleton[q]
            t.skeleton[q] = (x, y, rng.choice([r_ for r_ in plan.rotations[q] if r_ != rot]))
    elif r < 0.80:
        _pull(plan, t, rng.choice(sk), rng)
    elif r < 0.90 and len(sk) > 1:
        a, b = rng.sample(sk, 2)
        (xa, ya, ra), (xb, yb, rb) = t.skeleton[a], t.skeleton[b]
        if plan.columns.get(a) == plan.columns.get(b):
            t.skeleton[a], t.skeleton[b] = (xa, yb, ra), (xb, ya, rb)
        else:
            t.skeleton[a] = (xa, ya + rng.choice((-6, -4, 4, 6)) * GRID, ra)
    else:
        ref = rng.choice(sk)
        x, y, rot = t.skeleton[ref]
        t.skeleton[ref] = (x, y + rng.choice((-6, -4, 4, 6)) * GRID, rot)
    return t


def _search(plan: Plan, attached: set[str], seconds: float, seed: int,
            costs: Optional[Costs], max_candidates: int = 0) -> tuple[Candidate, int]:
    rng = random.Random(seed)
    cur = evaluate(plan, initial_state(plan), attached, costs)
    best = cur
    deadline = time.monotonic() + seconds
    start = time.monotonic()
    t_hot, t_cold = 25.0, 0.3
    n = 0
    while time.monotonic() < deadline and not (max_candidates and n >= max_candidates):
        if max_candidates:
            frac = n / max_candidates          # the same schedule on any PC
        else:
            frac = (time.monotonic() - start) / max(seconds, 1e-3)
        temp = t_hot * (t_cold / t_hot) ** frac
        cand = evaluate(plan, _neighbour(plan, cur.state, rng), attached, costs)
        n += 1
        delta = cand.score - cur.score
        if delta <= 0 or rng.random() < math.exp(-delta / max(temp, 1e-6)):
            cur = cand
            if cur.score < best.score:
                best = cur
        elif n % 200 == 0 and best.score < cur.score:
            cur = best                       # come back to the best now and then
    return best, n


def _extent(cand: Candidate) -> tuple[int, int, int, int]:
    """The drawing's box in mils: parts, texts, wires, symbols and labels."""
    x0, y0, x1, y1 = cand.layout.bounds
    xs, ys = [x0 * GRID, x1 * GRID], [y0 * GRID, y1 * GRID]
    d = cand.drawing
    for s in d.segments:
        xs += [s.x1, s.x2]
        ys += [s.y1, s.y2]
    for o in d.ports:
        xs.append(o["x"])
        ys += [o["y"] - 300, o["y"] + 300]
    for o in d.labels:
        xs += [o["x"], o["x"] + 50 * len(o["net"])]
        ys += [o["y"], o["y"] + 120]
    return min(xs), min(ys), max(xs), max(ys)


def _fit(size: str, box: tuple[int, int, int, int]) -> Optional[tuple[int, int]]:
    """The shift that centres the drawing on the sheet's free area, or None."""
    w, h = SHEETS[size]
    ax0, ay0, ax1, ay1 = _MARGIN, _TITLE, w - _MARGIN, h - _MARGIN
    bw, bh = box[2] - box[0], box[3] - box[1]
    if bw > ax1 - ax0 or bh > ay1 - ay0:
        return None
    cx = (ax0 + ax1 - bw) // 2 - box[0]
    cy = (ay0 + ay1 - bh) // 2 - box[1]
    return (cx // GRID * GRID, cy // GRID * GRID)


def measure(template: dict, drawing: Any) -> dict[str, Any]:
    """How a sheet reads, in numbers: the same for a draft and a hand template."""
    d = drawing
    length = sum(abs(s.x2 - s.x1) + abs(s.y2 - s.y1) for s in d.segments)
    ends: dict[tuple[int, int], set[bool]] = {}
    count: dict[tuple[int, int], int] = {}
    for s in d.segments:
        for e in s.ends():
            ends.setdefault(e, set()).add(s.horizontal)
            count[e] = count.get(e, 0) + 1
    corners = sum(1 for e, kinds in ends.items() if count[e] == 2 and len(kinds) == 2)
    by_check: dict[str, int] = {}
    for w in d.warnings:
        by_check[w["check"]] = by_check.get(w["check"], 0) + 1
    xs = [s.x1 for s in d.segments] + [s.x2 for s in d.segments] + \
        [b[i] for b in d.bodies.values() for i in (0, 2)]
    ys = [s.y1 for s in d.segments] + [s.y2 for s in d.segments] + \
        [b[i] for b in d.bodies.values() for i in (1, 3)]
    area = (max(xs) - min(xs)) * (max(ys) - min(ys)) / 1e6 if xs else 0.0
    return {"errors": len(d.errors), "wire_length_in": round(length / 1000, 1),
            "wire_segments": len(d.segments), "corners": corners,
            "junctions": len(d.auto_junctions),
            "crossings": by_check.get("crossing", 0),
            "through_body": by_check.get("through_body", 0),
            "text_overlaps": by_check.get("text_overlap", 0),
            "dangling": by_check.get("dangling", 0),
            "power_symbols": len(d.ports), "net_labels": len(d.labels),
            "area_sq_in": round(area, 1)}


def draft(plan: Any, symbols: dict, *, sheet: str = "", seconds: float = 12.0,
          seed: int = 1, costs: Optional[Costs] = None,
          png_path: str = "", max_candidates: int = 0) -> dict[str, Any]:
    """Lay out one plan sheet. Returns ``ok``, ``template``, ``report`` (the
    engine checker's), ``measures``, ``sheet_size`` and notes; with
    ``png_path``, a picture of the draft (``preview_png``). With
    ``max_candidates`` the search stops after that many candidates (the
    same result on any PC, for tests), or at ``seconds``, whichever first."""
    c = from_plan(plan, symbols, sheet)
    if c.problems:
        return {"ok": False, "errors": c.problems}
    if not c.parts:
        return {"ok": False, "errors": [f"no parts on sheet {sheet or 'main'}"]}
    data = plan.model_dump() if hasattr(plan, "model_dump") else dict(plan)
    sheets = {s.get("name"): s for s in data.get("sheets") or []}
    name = sheet or next(iter(sheets), "main")
    size = str((sheets.get(name) or {}).get("size") or "A4").upper()
    size = size if size in SHEETS else "A4"

    p = make_plan(c)
    attached = set(p.attachments)
    # Three shorter searches from different starts beat one long one: the
    # spread between seeds is the drafter's main weakness.
    chains = 3
    best, tried = None, 0
    for k in range(chains):
        cand, n = _search(p, attached, seconds / chains, seed * 1000 + k, costs,
                          max_candidates // chains if max_candidates else 0)
        tried += n
        if best is None or cand.score < best.score:
            best = cand
    if best.drawing is None:
        return {"ok": False, "errors": ["no legal placement found; give the search more "
                                        "seconds or split the sheet"],
                "candidates_tried": tried}
    box = _extent(best)
    shift, needed = None, size
    for s_ in [size] + [k for k in ("A3", "A2", "A1", "A0") if SHEETS[k][0] > SHEETS[size][0]]:
        shift = _fit(s_, box)
        if shift:
            needed = s_
            break
    if shift is None:
        shift = (_MARGIN - box[0]) // GRID * GRID, (_TITLE - box[1]) // GRID * GRID
    moved = State({r: (x + shift[0], y + shift[1], rot)
                   for r, (x, y, rot) in best.state.skeleton.items()},
                  dict(best.state.attached))
    final = evaluate(p, moved, attached, costs)
    d = final.drawing
    out: dict[str, Any] = {
        "ok": d is not None and d.ok,
        "template": final.template,
        "report": d.report() if d is not None else {},
        "measures": ({**measure(final.template, d),
                      "outline_overlaps": len(outline_overlaps(final.layout))}
                     if d is not None else {}),
        "score": round(final.score, 1),
        "candidates_tried": tried,
        "sheet": name,
        "sheet_size": size,
        "roles": {r: a.role for r, a in p.attachments.items()},
        "columns": p.columns,
    }
    if needed != size:
        out["sheet_size_needed"] = needed
        out["notes"] = [f"the drawing does not fit {size}; it fits {needed}: set the "
                        f"sheet size or split the sheet"]
    if final.routed and final.routed.fallbacks:
        out.setdefault("notes", []).append(
            "named by label instead of wired (no clean route): "
            + ", ".join(final.routed.fallbacks))
    touching = outline_overlaps(final.layout) if final.layout else []
    if touching:
        out.setdefault("notes", []).append(
            "outlines that meet (design_audit_schematic reports them as overlaps): "
            + ", ".join(f"{a}/{b}" for a, b in touching))
    if c.notes:
        out.setdefault("notes", []).extend(c.notes)
    if png_path and d is not None:
        try:
            out["preview_png"] = st.render_png(d, png_path, title=f"Boardwright draft: {name}")
        except ImportError:
            out["preview_error"] = "matplotlib is not installed"
        except Exception as exc:  # a failed picture must not hide the draft
            out["preview_error"] = f"{type(exc).__name__}: {exc}"
    return out
